/* ─── Form fields ─── */
.field { display: grid; gap: var(--s2); min-width: 0; }
.field-hint { overflow-wrap: anywhere; font-size: var(--text-xs); color: var(--muted); margin-top: var(--s1); }
.input, .select { height: var(--control-md); padding-block: 0; }
.input, .select, .textarea { width: 100%; min-width: 0; background: transparent; border: 1px solid var(--foreground); border-radius: var(--radius); padding: var(--s3) var(--s4); color: var(--foreground); }
/* Native select: one chevron in every browser and theme. Two gradients in currentColor draw the V, so there is no image to colour per theme. */
.select { appearance: none; -webkit-appearance: none; padding-inline-end: calc(var(--s4) + 1em); background-image: linear-gradient(to bottom left, transparent 40%, currentColor 40%, currentColor 60%, transparent 60%), linear-gradient(to bottom right, transparent 40%, currentColor 40%, currentColor 60%, transparent 60%); background-repeat: no-repeat; background-size: 0.4em 0.4em, 0.4em 0.4em; background-position: calc(100% - var(--s4) - 0.4em) 50%, calc(100% - var(--s4)) 50%; }
.input::placeholder, .textarea::placeholder { color: var(--muted); }
.input:focus, .select:focus, .textarea:focus { outline: 2px solid var(--accent); outline-offset: 0; }
.input[aria-invalid="true"] { border-color: var(--danger); }
.textarea { resize: vertical; min-height: 120px; line-height: 1.6; }
.input-sm { height: var(--control-sm); padding: 0 10px; font-size: var(--text-sm); }
.input-lg { height: var(--control-lg); padding: 0 18px; }
/* A control at a field's right end (a list picker, a clear button): --s3 in from the edge, the text stops before it. */
.input-wrap { position: relative; min-width: 0; }
.input-wrap > .input { padding-inline-end: var(--s9); }
.input-end { position: absolute; inset-inline-end: var(--s3); top: 50%; transform: translateY(-50%); min-height: var(--s6); min-width: var(--s6); display: inline-grid; place-items: center; }
/* Text edited in place inside a row: no border; padding with a matching negative margin keeps the text in line with its
   neighbours while the focus ring clears it by --s2. The right edge stays put, so the next control keeps its gap. */
.input-bare { display: block; width: calc(100% + var(--s2)); margin: calc(-1 * var(--s2)) 0 calc(-1 * var(--s2)) calc(-1 * var(--s2)); padding: var(--s2); border: 0; background: transparent; resize: none; font: inherit; line-height: inherit; color: inherit; }
.input-bare:focus-visible { outline-offset: 0; }
/* A labelled on/off: a native checkbox drawn as a square switch. */
.switch { display: inline-flex; align-items: center; gap: var(--s3); cursor: pointer; }
.switch input { appearance: none; width: 36px; height: 20px; margin: 0; flex: none; border: 1px solid var(--foreground); position: relative; cursor: pointer; transition: background var(--fast); }
.switch input::after { content: ""; position: absolute; top: 3px; inset-inline-start: 3px; width: 12px; height: 12px; background: var(--foreground); transition: transform var(--base) var(--ease), background var(--fast); }
.switch input:checked { background: var(--foreground); }
.switch input:checked::after { transform: translateX(calc(16px * var(--dir, 1))); background: var(--background); }
.switch input:disabled { opacity: 0.5; cursor: not-allowed; }
/* Settings: label left, control right, a rule between rows. */
.setting { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: var(--s2) var(--s5); padding: var(--s4) 0; }
.setting + .setting { border-top: 1px solid var(--rule); }
.setting > :first-child { display: grid; gap: 2px; }

/* Segmented control: one choice of a few, always visible. */
.seg { display: flex; align-items: center; gap: var(--s2); }
.seg > .muted { margin-inline-end: var(--s1); }
.seg-opt { padding: var(--s1) var(--s3); border: 1px solid var(--rule); color: var(--muted); }
.seg-opt + .seg-opt { margin-inline-start: calc(-1 * var(--s2) - 1px); }
.seg-opt[aria-pressed="true"], .seg-opt[aria-checked="true"] { color: var(--background); background: var(--foreground); border-color: var(--foreground); }
.seg-opt:not([aria-pressed="true"]):not([aria-checked="true"]):hover { color: var(--foreground); }

/* ─── Avatar, tag, stat ─── */
.avatar { display: inline-grid; place-items: center; width: 32px; height: 32px; flex: none; background: var(--foreground); color: var(--background); font-size: var(--text-xs); font-weight: 500; text-transform: uppercase; overflow: hidden; }
.avatar img { width: 100%; height: 100%; object-fit: cover; }
.avatar-sm { width: 24px; height: 24px; font-size: var(--text-xs); }
.avatar-lg { width: 48px; height: 48px; font-size: var(--text-sm); }
.avatar-line { background: transparent; color: var(--foreground); box-shadow: inset 0 0 0 1px var(--foreground); }
.avatar-group { display: inline-flex; }
.avatar-group > .avatar { box-shadow: 0 0 0 2px var(--background); }
.avatar-group > .avatar + .avatar { margin-inline-start: calc(-1 * var(--s2)); }
.tag { overflow-wrap: anywhere; display: inline-flex; align-items: center; gap: var(--s2); padding: 2px var(--s3); font-size: var(--text-sm); box-shadow: inset 0 0 0 1px var(--rule); }
.tag button { min-inline-size: 24px; min-block-size: 24px; /* WCAG 2.5.8 target size; found by e2e */ padding: 0 var(--s1); color: var(--muted); }
.tag button:hover { color: var(--foreground); }
.stat { display: grid; gap: var(--s1); align-content: start; /* a Stat without a note must not stretch its rows in a taller grid cell */ }
.stat-value { font-family: var(--font-display); font-weight: 700; font-size: var(--display-sm); letter-spacing: -0.03em; line-height: 1; }
.stat-note { font-size: var(--text-sm); color: var(--muted); }

/* Multi select: a bordered box holding tags and the text input; the list drops below. */
.multi-select { position: relative; width: 100%; }
.multi-select-box { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s2); min-height: var(--s7); padding: var(--s2) var(--s3); border: 1px solid var(--foreground); border-radius: var(--radius); }
.multi-select-box:focus-within { outline: 2px solid var(--accent); }
.multi-select[data-invalid] .multi-select-box { border-color: var(--danger); }
.multi-select[data-disabled] .multi-select-box { opacity: 0.5; }
.multi-select-input { flex: 1 1 8ch; min-width: 8ch; padding: var(--s1) 0; background: transparent; border: 0; color: var(--foreground); outline: 0; }
.multi-select-input::placeholder { color: var(--muted); }
.multi-select-list { position: absolute; inset-inline-start: 0; inset-inline-end: 0; top: calc(100% + var(--s1)); z-index: var(--z-drawer); max-height: 16rem; overflow-y: auto; margin: 0; padding: var(--s1) 0; list-style: none; background: var(--background); border: 1px solid var(--foreground); }
.multi-select-option { padding: var(--s2) var(--s4); font-size: var(--text-sm); cursor: pointer; }
.multi-select-option[data-active] { background: var(--foreground); color: var(--background); }
.multi-select-option[aria-selected="true"]::after { content: " ✓" / ""; }
.multi-select-option[aria-disabled="true"] { opacity: 0.5; cursor: not-allowed; }
.multi-select-empty { padding: var(--s3) var(--s4); font-size: var(--text-sm); color: var(--muted); }
.multi-select[data-size="sm"] .multi-select-box { min-height: var(--control-sm); }
.multi-select[data-size="lg"] .multi-select-box { min-height: var(--control-lg); }

